var contador;
function getPageCategory(url, mql, e, a){

	if(mql.matches){
		if(contador == 0){
			contador = 1;
			a.parentNode.children[1].style.display = "none";
		}else{
			contador = 0;
			a.parentNode.children[1].style.display = "block";
		}
		e.preventDefault();
        e.stopPropagation();

	}else{
		location.href = url;
	}
}

